import{_ as t,o as a,c as r,ak as s}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Chainy testing and evaluation","description":"Updated October 23, 2026. Christian owns technical tests; Miguel UI checks; Luis visual/import checks; Sean evidence procedures and authored records; Sherwin readiness decisio","frontmatter":{"title":"Chainy testing and evaluation","description":"Updated October 23, 2026. Christian owns technical tests; Miguel UI checks; Luis visual/import checks; Sean evidence procedures and authored records; Sherwin readiness decisio","source":"docs/qa-evaluation.md","category":"Research & evaluation","sourceUpdated":"2026-10-23T16:51:22+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/qa-evaluation.md","filePath":"content/docs/qa-evaluation.md"}'),n={name:"content/docs/qa-evaluation.md"};function i(o,e,c,d,l,p){return a(),r("div",null,[...e[0]||(e[0]=[s('<div><h1 id="chainy-testing-and-evaluation">Chainy testing and evaluation<a class="header-anchor" href="#chainy-testing-and-evaluation" aria-label="Link to this section">​</a></h1><p>Updated October 23, 2026. Christian owns technical tests; Miguel UI checks; Luis visual/import checks; Sean evidence procedures and authored records; Sherwin readiness decisions. Specifications below are <strong>not passed tests</strong>.</p><h2 id="core-game-checks">Core game checks<a class="header-anchor" href="#core-game-checks" aria-label="Link to this section">​</a></h2><p>Use <a href="/Chainy-Docs/content/docs/requirements/product-requirements.html">V2-R01–12</a> and the GDD&#39;s GP-01–GP-14. Record build revision, device, steps, expected/actual result, artifact and responsible tester. Use synthetic data internally.</p><table><thead><tr><th>Check</th><th>Expected result</th></tr></thead><tbody><tr><td>Offline install/start</td><td>Named Android build opens and completes the core chapter without network</td></tr><tr><td>Profile and versions</td><td>Correct local demo profile loads; switching clears prior state; incompatible data gets a safe recovery path</td></tr><tr><td>Exploration/dialogue</td><td>Movement, collision, interaction and load recovery work; overlay locks world input and restores it on close</td></tr><tr><td>W01–W04 economy</td><td>Reward 12 once; lantern price 8 + fee 1; balance 3; cancel is free; ownership and free equip restore workshop</td></tr><tr><td>Atomic save</td><td>Balance, inventory, ledger, quest and restoration agree after commit, failure, repeat taps, retry and relaunch</td></tr><tr><td>B01–B03/demo B07</td><td>Same purchase record; three blocks linked to trusted checkpoint; reject price 6 versus original 8; restore beacon</td></tr><tr><td>Quest/journal</td><td>Valid prerequisites/states, early pickups retained, no repeated rewards; evidence labels never imply mastery</td></tr><tr><td>Touch and feedback</td><td>Clear objectives, readable small-screen controls, non-color cues, audio-off usability and actionable save errors</td></tr><tr><td>Pause/interruption/update</td><td>Supported checkpoint resume, separated profiles and tested signed update; no silent data loss</td></tr><tr><td>End-to-end</td><td>Core chapter completes on the beta device without core-blocking/data-loss defects; remaining scope is clearly disclosed</td></tr></tbody></table><p>AI A01–A03 is tested only if admitted: an actual classifier uses learner examples; practice and reserved final cases stay separate; first-final-attempt evidence is not overwritten by replay. Authored responses must not be labeled trained AI. Wordle, BlockMatch and later teacher services are not core acceptance blockers.</p><h2 id="beta-readiness">Beta readiness<a class="header-anchor" href="#beta-readiness" aria-label="Link to this section">​</a></h2><p><strong>November 10, 2026 — Cryptita Plays community beta testing.</strong> This replaces the Marinduque school event. Target core freeze October 30; protect integration/device tests October 31–November 6, then blocker fixes, regression and rehearsal November 7–9.</p><p>Christian confirms tested build/recovery; Miguel confirms UI; Sean confirms permitted evidence collection; Sherwin confirms community arrangements/devices and decides go/no-go. Dates do not establish consent, readiness or school acceptance. Record unresolved requirements honestly.</p><h2 id="evaluation-and-safe-evidence">Evaluation and safe evidence<a class="header-anchor" href="#evaluation-and-safe-evidence" aria-label="Link to this section">​</a></h2><p>Confirm respondents, sample size, assistance policy, instruments, analysis, custodian and permissions with the appropriate adviser/organizer. The school&#39;s exact “ISO 2010” instrument and completion formula remain unknown. Community feedback is not automatically the required pilot-area study.</p><p>If approved, explain the session, select the correct local profile, gather the agreed baseline measure, give consistent instructions, record assistance/interruptions, play the accepted chapter and collect approved follow-up/usability evidence. Confirm usable collection before closing; keep identities and raw records in restricted storage.</p><p>Game completion, vocabulary success and encyclopedia labels are not validated learning measures. Separate practice, first independent assessment and replay. An observed pre/post difference does not by itself prove causation.</p><h2 id="results-and-defense">Results and defense<a class="header-anchor" href="#results-and-defense" aria-label="Link to this section">​</a></h2><p>Use actual November 10 evidence only: analysis and retested fixes November 11–13; manuscript November 14–16; rehearsal November 17–20; <strong>pre-final November 21</strong>. Missing research approval or required evidence is a blocker, never a result to invent. See the <a href="/Chainy-Docs/content/docs/manuscript-evidence-map.html">official evidence map</a>.</p></div>',1)])])}const m=t(n,[["render",i]]);export{u as __pageData,m as default};
